   all text          → addLabel (grades, caption, velocity callouts)
──────────────────────────────────────────────────────────────────────────── */

/* ── constants ───────────────────────────────────────────────────────────── */
const OIL_TOP = 4.95, OIL_BOT = 0.40, R_SPH = 0.23;
const Y_START = OIL_TOP - R_SPH;          // 4.72
const Y_END   = OIL_BOT + R_SPH;          // 0.63
const FALL    = Y_START - Y_END;          // 4.09
const RACE_SPEED = 1.6;                   // world units / s per unit rel. speed
const ETA = [1.00, 1.14, 1.57, 2.44];     // relative dynamic viscosity anchors
const OIL_ANCHORS = [
  { top: 0xf5dfa0, bot: 0xecd08a },       // SAE 20
  { top: 0xf2c75a, bot: 0xe8b444 },       // SAE 30
  { top: 0xf0b04a, bot: 0xe88a2e },       // SAE 40
  { top: 0xf2755a, bot: 0xe8422c }        // SAE 50
];
const CYL = [
  { grade: 20, x: -3.6, y0: 1.31, vrel: 1.000, vcm: 4.0 },
  { grade: 30, x: -1.2, y0: 1.76, vrel: 0.875, vcm: 3.5 },
  { grade: 40, x:  1.2, y0: 2.63, vrel: 0.635, vcm: 2.5 },
  { grade: 50, x:  3.6, y0: 3.45, vrel: 0.410, vcm: 1.6 }
];

/* ── lighting ────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xd9b26a, 0.65));
scene.add(new THREE.AmbientLight(0xffffff, 0.25));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.95);
keyLight.position.set(-6, 10, 9);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xbcd6ea, 0.3);
fillLight.position.set(6, 4, -7);
scene.add(fillLight);

/* ── slab ────────────────────────────────────────────────────────────────── */
const slabGeom = new THREE.BoxGeometry(11, 0.45, 3);
{
  const p = slabGeom.attributes.position, n = slabGeom.attributes.normal;
  const arr = new Float32Array(p.count * 3);
  const cBack = new THREE.Color(0xf2d38f), cFront = new THREE.Color(0xe39f2c);
  const cSide = new THREE.Color(0xd08c1c), tmp = new THREE.Color();
  for (let i = 0; i < p.count; i++) {
    if (n.getY(i) > 0.5) {
      const t = (p.getZ(i) + 1.5) / 3;
      tmp.copy(cBack).lerp(cFront, t);
    } else tmp.copy(cSide);
    arr[i * 3] = tmp.r; arr[i * 3 + 1] = tmp.g; arr[i * 3 + 2] = tmp.b;
  }
  slabGeom.setAttribute('color', new THREE.BufferAttribute(arr, 3));
}
const slab = new THREE.Mesh(
  slabGeom,
  new THREE.MeshPhongMaterial({ vertexColors: true, shininess: 14, specular: 0x352000 })
);
slab.position.y = -0.225;
scene.add(slab);
const slabEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(slabGeom),
