);
slabEdges.position.copy(slab.position);
scene.add(slabEdges);
registerInteractive(slab, {
  title: 'Common base',
  tooltip: 'All four tests share one slab',
  body: 'Every cylinder stands on the same slab and holds the same amount of oil to the same level, so the only difference between the four tests is the oil grade itself.'
});

/* ── soft contact-shadow decal texture ───────────────────────────────────── */
function shadowTexture() {
  const cv = document.createElement('canvas');
  cv.width = cv.height = 128;
  const ctx = cv.getContext('2d');
  const gr = ctx.createRadialGradient(64, 64, 3, 64, 64, 62);
  gr.addColorStop(0.00, 'rgba(85,55,12,0.42)');
  gr.addColorStop(0.50, 'rgba(85,55,12,0.20)');
  gr.addColorStop(1.00, 'rgba(85,55,12,0.0)');
