// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   slab              → BoxGeometry(11.6,0.70,3.2) MeshBasic vertexColors gold
   slab outline      → EdgesGeometry lines #a96c12
   contact shadow    → PlaneGeometry(2.2,2.2) radial-gradient canvas decal
   tube body         → CylinderGeometry(0.37,0.37,4.88, open) glass phong 0.25
   pour spout        → CylinderGeometry(0.55,0.37,0.50, open) glass
   spout beak        → BufferGeometry 2 triangles, glass
   rim rings         → TorusGeometry thin, #7fa8b8
   tube bottom disc  → CircleGeometry(0.37) glass
   hex foot          → 2 x CylinderGeometry(radialSegments 6) #d8e4ea
   oil column        → CylinderGeometry(0.33,0.33,4.55) MeshBasic vertexColors 0.84
   sphere            → SphereGeometry(0.27,48,32) phong steel, drawn OVER oil
   glass streak      → PlaneGeometry white 0.32
   leader line       → Line (2 pts) to terminal-velocity label
   all text          → addLabel (caption largest, grades, velocity callouts)
──────────────────────────────────────────────────────────────────────────── */

/* ── constants ───────────────────────────────────────────────────────────── */
const R_OUT = 0.37, R_OIL = 0.33, R_SPH = 0.27;
const OIL_TOP = 4.95, OIL_BOT = 0.40, OIL_H = OIL_TOP - OIL_BOT;
const Y_START = OIL_TOP - R_SPH;          // 4.68
const Y_END   = OIL_BOT + R_SPH;          // 0.67
const FALL    = Y_START - Y_END;          // 4.01
const RACE_SPEED = 1.55;
const ETA = [1.00, 1.14, 1.57, 2.44];
const OIL_ANCHORS = [
  { top: 0xf7e2a2, bot: 0xecd08a },       // SAE 20  pale yellow
  { top: 0xf5cb56, bot: 0xe8b444 },       // SAE 30  yellow-gold
  { top: 0xf5b24a, bot: 0xe8862a },       // SAE 40  amber-orange
  { top: 0xf87a5c, bot: 0xe83a24 }        // SAE 50  orange-red
];
const CYL = [
  { grade: 20, x: -4.05, y0: 1.31, vrel: 1.000, vcm: 4.0 },
  { grade: 30, x: -1.35, y0: 1.76, vrel: 0.875, vcm: 3.5 },
  { grade: 40, x:  1.35, y0: 2.63, vrel: 0.635, vcm: 2.5 },
  { grade: 50, x:  4.05, y0: 3.45, vrel: 0.410, vcm: 1.6 }
];

/* ── lighting (neutral white — no gold ground tint) ──────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xf2f2f2, 0.55));
scene.add(new THREE.AmbientLight(0xffffff, 0.45));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-6, 10, 9);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(6, 4, -7);
scene.add(fillLight);

/* ── slab ────────────────────────────────────────────────────────────────── */
const SLAB_W = 11.6, SLAB_H = 0.70, SLAB_D = 3.2;
const slabGeom = new THREE.BoxGeometry(SLAB_W, SLAB_H, SLAB_D);
{
  const p = slabGeom.attributes.position, n = slabGeom.attributes.normal;
  const arr = new Float32Array(p.count * 3);
  const cBack = new THREE.Color(0xf6dc9b), cFront = new THREE.Color(0xe7a733);
  const cFrTop = new THREE.Color(0xe8ad3b), cFrBot = new THREE.Color(0xcf8e1a);
  const cSide = new THREE.Color(0xd08c1c), tmp = new THREE.Color();
  for (let i = 0; i < p.count; i++) {
    if (n.getY(i) > 0.5) {
      const t = (p.getZ(i) + SLAB_D / 2) / SLAB_D;
      tmp.copy(cBack).lerp(cFront, t);
    } else if (n.getZ(i) > 0.5) {
      const t = (p.getY(i) + SLAB_H / 2) / SLAB_H;
      tmp.copy(cFrBot).lerp(cFrTop, t);
    } else tmp.copy(cSide);
    arr[i * 3] = tmp.r; arr[i * 3 + 1] = tmp.g; arr[i * 3 + 2] = tmp.b;
  }
  slabGeom.setAttribute('color', new THREE.BufferAttribute(arr, 3));
}
const slab = new THREE.Mesh(slabGeom, new THREE.MeshBasicMaterial({ vertexColors: true }));
slab.position.y = -SLAB_H / 2;
scene.add(slab);
const slabEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(slabGeom),
  new THREE.LineBasicMaterial({ color: 0xa96c12 })
);
slabEdges.position.copy(slab.position);
scene.add(slabEdges);
registerInteractive(slab, {
  title: 'Common base',
  tooltip: 'All four tests share one slab',
  body: 'Every cylinder stands on the same slab and holds oil to exactly the same level, so the only difference between the four tests is the oil grade itself.'
});

/* ── soft contact-shadow decal texture ───────────────────────────────────── */
function shadowTexture() {
  const cv = document.createElement('canvas');
  cv.width = cv.height = 128;
  const ctx = cv.getContext('2d');
  const gr = ctx.createRadialGradient(64, 64, 3, 64, 64, 62);
  gr.addColorStop(0.00, 'rgba(95,62,14,0.38)');
  gr.addColorStop(0.50, 'rgba(95,62,14,0.17)');
  gr.addColorStop(1.00, 'rgba(95,62,14,0.0)');
  ctx.fillStyle = gr; ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(cv);
}
const SHADOW_TEX = shadowTexture();

/* ── oil vertex-colour gradient (vertical + soft side shading) ───────────── */
function setOilColors(geom, cTop, cBot) {
  const p = geom.attributes.position;
  let attr = geom.attributes.color;
  if (!attr) {
    attr = new THREE.BufferAttribute(new Float32Array(p.count * 3), 3);
    geom.setAttribute('color', attr);
  }
  const a = new THREE.Color(cTop), b = new THREE.Color(cBot), c = new THREE.Color();
  for (let i = 0; i < p.count; i++) {
    const t = THREE.MathUtils.clamp((p.getY(i) + OIL_H / 2) / OIL_H, 0, 1);
    c.copy(b).lerp(a, t);
    const xr = THREE.MathUtils.clamp(p.getX(i) / R_OIL, -1, 1);
    const s = 1.07 - 0.19 * (xr * 0.5 + 0.5);
    attr.setXYZ(i,
      Math.min(1, c.r * s), Math.min(1, c.g * s), Math.min(1, c.b * s));
  }
  attr.needsUpdate = true;
}

/* ── one graduated cylinder ──────────────────────────────────────────────── */
function makeCylinder(cTop, cBot) {
  const grp = new THREE.Group();
  const mats = [];
  const track = (m) => { m.transparent = true; mats.push({ m, base: m.opacity }); return m; };
  const glass = () => track(new THREE.MeshPhongMaterial({
    color: 0xdceaf2, transparent: true, opacity: 0.26, depthWrite: false,
    side: THREE.DoubleSide, shininess: 110, specular: 0xffffff
  }));

  // tube body 0.12 → 5.00
  const bodyH = 4.88;
  const body = new THREE.Mesh(new THREE.CylinderGeometry(R_OUT, R_OUT, bodyH, 48, 1, true), glass());
  body.position.y = 0.12 + bodyH / 2; body.renderOrder = 6; grp.add(body);

  // pour spout flare 5.00 → 5.50
  const spout = new THREE.Mesh(new THREE.CylinderGeometry(0.55, R_OUT, 0.50, 48, 1, true), glass());
  spout.position.y = 5.25; spout.renderOrder = 6; grp.add(spout);

  // beak
  const r = 0.55, yTop = 5.5;
  const a1 = THREE.MathUtils.degToRad(-24), a2 = THREE.MathUtils.degToRad(24);
  const p1 = new THREE.Vector3(r * Math.sin(a1), yTop, r * Math.cos(a1));
  const p2 = new THREE.Vector3(r * Math.sin(a2), yTop, r * Math.cos(a2));
  const mid = new THREE.Vector3(0, yTop - 0.02, r);
  const tip = new THREE.Vector3(0, yTop - 0.12, 0.86);
  const beakGeom = new THREE.BufferGeometry().setFromPoints([p1, mid, tip, mid, p2, tip]);
  beakGeom.computeVertexNormals();
  const beak = new THREE.Mesh(beakGeom, glass());
  beak.renderOrder = 6; grp.add(beak);

  // bottom disc of tube
  const disc = new THREE.Mesh(new THREE.CircleGeometry(R_OUT, 44), glass());
  disc.rotation.x = -Math.PI / 2; disc.position.y = 0.125; grp.add(disc);

  // rim rings
  const ringMat = track(new THREE.MeshBasicMaterial({ color: 0x7fa8b8, transparent: true, opacity: 0.8 }));
  [[0.55, 5.50], [R_OUT, 5.00], [R_OUT, 0.14]].forEach(([rr, yy]) => {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(rr, 0.014, 8, 52), ringMat);
    ring.rotation.x = Math.PI / 2; ring.position.y = yy; ring.renderOrder = 7; grp.add(ring);
  });

  // hexagonal stepped foot
  const footMat = track(new THREE.MeshPhongMaterial({
    color: 0xdde8ee, transparent: true, opacity: 0.95, shininess: 70, specular: 0xffffff
  }));
  const f1 = new THREE.Mesh(new THREE.CylinderGeometry(0.58, 0.72, 0.14, 6), footMat);
  f1.position.y = 0.07; f1.rotation.y = Math.PI / 6; grp.add(f1);
  const f2 = new THREE.Mesh(new THREE.CylinderGeometry(0.40, 0.55, 0.24, 6), footMat);
  f2.position.y = 0.26; f2.rotation.y = Math.PI / 6; grp.add(f2);

  // contact shadow
  const shMat = track(new THREE.MeshBasicMaterial({
    map: SHADOW_TEX, transparent: true, opacity: 1, depthWrite: false
  }));
  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 2.2), shMat);
  shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.007;
  shadow.renderOrder = 0; grp.add(shadow);

  // oil column — flat, saturated, matches the printed palette
  const oilGeom = new THREE.CylinderGeometry(R_OIL, R_OIL, OIL_H, 44, 14);
  setOilColors(oilGeom, cTop, cBot);
  const oilMat = track(new THREE.MeshBasicMaterial({
    vertexColors: true, transparent: true, opacity: 0.84,
    depthWrite: false, side: THREE.FrontSide
  }));
  const oil = new THREE.Mesh(oilGeom, oilMat);
  oil.position.y = (OIL_BOT + OIL_TOP) / 2; oil.renderOrder = 2; grp.add(oil);

  // steel sphere — transparent flag + high renderOrder so it draws IN FRONT of the oil
  const sphMat = track(new THREE.MeshPhongMaterial({
    color: 0xa2a2a2, specular: 0xffffff, shininess: 120,
    transparent: true, opacity: 1, depthWrite: true
  }));
  const sphere = new THREE.Mesh(new THREE.SphereGeometry(R_SPH, 48, 32), sphMat);
  sphere.position.y = Y_START; sphere.renderOrder = 4; grp.add(sphere);

  // tiny specular glint on the sphere (billboarded disc)
  const glintMat = track(new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.85, depthTest: false
  }));
  const glint = new THREE.Mesh(new THREE.CircleGeometry(0.052, 20), glintMat);
  glint.renderOrder = 5; grp.add(glint);

  // vertical glass highlight streaks
  const streakMat = track(new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.32, depthWrite: false
  }));
  const streak = new THREE.Mesh(new THREE.PlaneGeometry(0.075, 4.3), streakMat);
  streak.position.set(-0.17, 2.62, 0.355); streak.renderOrder = 8; grp.add(streak);
  const streak2 = new THREE.Mesh(new THREE.PlaneGeometry(0.035, 3.9), streakMat);
  streak2.position.set(0.20, 2.6, 0.345); streak2.renderOrder = 8; grp.add(streak2);

  // leader line for terminal-velocity callout
  const leadMat = track(new THREE.LineBasicMaterial({ color: 0x555555, transparent: true, opacity: 0.9 }));
  const leadGeom = new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0.42, Y_START, 0.30), new THREE.Vector3(1.02, Y_START, 0.30)]
  );
  const leader = new THREE.Line(leadGeom, leadMat);
  leader.renderOrder = 10; grp.add(leader);

  return { group: grp, mats, oilGeom, oil, sphere, glint, leader, leadGeom, fade: 1 };
}

/* ── build the four cylinders + the tunable one ──────────────────────────── */
const tubes = CYL.map((c, i) => {
  const t = makeCylinder(OIL_ANCHORS[i].top, OIL_ANCHORS[i].bot);
  t.group.position.x = c.x;
  t.sphere.position.y = c.y0;
  scene.add(t.group);
  registerInteractive(t.sphere, {
    title: `Sphere in SAE ${c.grade} oil`,
    tooltip: `SAE ${c.grade}: terminal speed ${c.vcm.toFixed(1)} cm/s`,
    body: `Stokes' law gives v = 2r²(ρs − ρf)g / (9η), so terminal velocity is inversely proportional to viscosity. With relative viscosity η = ${ETA[i].toFixed(2)} this sphere settles at ${c.vcm.toFixed(1)} cm/s — after the same elapsed time it has fallen only ${(c.vrel * 100).toFixed(0)}% as far as the sphere in SAE 20.`
  });
  registerInteractive(t.oil, {
    title: `SAE ${c.grade} motor oil`,
    tooltip: `SAE ${c.grade} oil column`,
    body: 'Higher SAE grades are more viscous: the oil resists flow more strongly and exerts a larger drag force on anything moving through it. The deeper colour here codes the grade.'
  });
  return t;
});

const single = makeCylinder(OIL_ANCHORS[1].top, OIL_ANCHORS[1].bot);
single.group.position.x = 0;
single.group.visible = false;
single.sphere.position.y = Y_START;
scene.add(single.group);
registerInteractive(single.sphere, {
  title: 'Tunable cylinder',
  tooltip: 'Drag the SAE slider to change the oil',
  body: 'Viscosity is continuous, not just four discrete grades. As the slider raises the SAE number the oil darkens, η grows, and the sphere descends more and more slowly.'
});

/* ── camera (after all geometry) ─────────────────────────────────────────── */
const COMPARE_VIEW = { projection: 'perspective', azimuthDeg: 90, elevationDeg: 12, rollDeg: 0, heightFraction: 0.68 };
const SINGLE_VIEW  = { projection: 'perspective', azimuthDeg: 90, elevationDeg: 10, rollDeg: 0, heightFraction: 0.95, target: [0, 2.7, 0] };
setCameraView(COMPARE_VIEW);
controls.minAzimuthAngle = THREE.MathUtils.degToRad(-35);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(35);
controls.minPolarAngle = THREE.MathUtils.degToRad(55);
controls.maxPolarAngle = THREE.MathUtils.degToRad(90);
controls.enablePan = false;

function applyView(mode) {
  if (mode === 'single') {
    setCameraView(SINGLE_VIEW);
    const t = new THREE.Vector3(0, 2.7, 0);
    camera.position.sub(t).multiplyScalar(0.50).add(t);
    camera.near = 0.05;
    camera.updateProjectionMatrix();
    controls.update();
  } else {
    setCameraView(COMPARE_VIEW);
  }
}

/* ── labels (caption largest, then grades, then callouts) ────────────────── */
const captionLbl = addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.34, SLAB_D / 2 + 0.02),
  { fontSize: '60px', color: '#3f2708' });

const gradeLbls = CYL.map(c => addLabel(String(c.grade), new THREE.Vector3(c.x, 0.03, 1.05),
  { fontSize: '54px', color: '#2e2e2e' }));

const velLbls = CYL.map(c => addLabel(`${c.vcm.toFixed(1)} cm/s`,
  new THREE.Vector3(c.x + 1.15, c.y0, 0.32),
  { fontSize: '34px', color: '#14486e', background: 'rgba(255,255,255,0.85)' }));

const singleGradeLbl = addLabel('SAE 30', new THREE.Vector3(0, 0.03, 1.05),
  { fontSize: '54px', color: '#2e2e2e' });
const singleVelLbl = addLabel('3.5 cm/s', new THREE.Vector3(1.2, Y_START, 0.32),
  { fontSize: '34px', color: '#14486e', background: 'rgba(255,255,255,0.85)' });

function setLblOpacity(entry, o) { entry.div.style.opacity = String(o); }
velLbls.forEach(l => setLblOpacity(l, 0));
setLblOpacity(singleGradeLbl, 0);
setLblOpacity(singleVelLbl, 0);

/* ── physics helpers ─────────────────────────────────────────────────────── */
function etaFor(g) {
  const gg = THREE.MathUtils.clamp(g, 20, 50);
  const i = Math.min(2, Math.floor((gg - 20) / 10));
  const t = (gg - 20 - 10 * i) / 10;
  return Math.exp(Math.log(ETA[i]) * (1 - t) + Math.log(ETA[i + 1]) * t);
}
function vcmFor(g) { return 4.0 / etaFor(g); }
const _cA = new THREE.Color(), _cB = new THREE.Color();
function oilColorsFor(g) {
  const gg = THREE.MathUtils.clamp(g, 20, 50);
  const i = Math.min(2, Math.floor((gg - 20) / 10));
  const t = (gg - 20 - 10 * i) / 10;
  _cA.setHex(OIL_ANCHORS[i].top).lerp(new THREE.Color(OIL_ANCHORS[i + 1].top), t);
  _cB.setHex(OIL_ANCHORS[i].bot).lerp(new THREE.Color(OIL_ANCHORS[i + 1].bot), t);
  return { top: _cA.getHex(), bot: _cB.getHex() };
}

/* ── state + UI wiring ───────────────────────────────────────────────────── */
const state = {
  race: false, raceT: 0,
  labels: false,
  mode: 'compare',
  grade: 30,
  singleT: 0,
  fadeCompare: 1, fadeSingle: 0,
  sweep: null
};

const elRace = document.getElementById('btnRace');
const elSae = document.getElementById('saeGrade');
const elSaeOut = document.getElementById('saeOut');
const elSaeInfo = document.getElementById('saeInfo');
const elLabels = document.getElementById('terminalLabels');
const elCompare = document.getElementById('btnCompare');
const elSingle = document.getElementById('btnSingle');
const elPrev = document.getElementById('btnPrev');
const elNext = document.getElementById('btnNext');
const elStepTitle = document.getElementById('stepTitle');
const elStepText = document.getElementById('stepText');

function setGrade(g, fromUI) {
  state.grade = g;
  if (!fromUI) elSae.value = String(Math.round(g));
  elSaeOut.textContent = String(Math.round(g));
  const cols = oilColorsFor(g);
  setOilColors(single.oilGeom, cols.top, cols.bot);
  const e = etaFor(g), v = vcmFor(g);
  elSaeInfo.innerHTML = `relative viscosity η = ${e.toFixed(2)}<br>terminal velocity v = ${v.toFixed(1)} cm/s`;
  singleGradeLbl.div.innerHTML = `SAE ${Math.round(g)}`;
  singleVelLbl.div.innerHTML = `${v.toFixed(1)} cm/s`;
}

function syncRaceBtn() {
  elRace.textContent = state.race ? '■ Stop / reset spheres' : '▶ Release all four spheres';
  elRace.classList.toggle('active', state.race);
}

elRace.addEventListener('click', () => {
  state.race = !state.race;
  state.raceT = 0;
  syncRaceBtn();
});

elSae.addEventListener('input', () => { state.sweep = null; setGrade(parseFloat(elSae.value), true); });
elLabels.addEventListener('change', () => { state.labels = elLabels.checked; });

function setMode(m) {
  state.mode = m;
  elCompare.classList.toggle('active', m === 'compare');
  elSingle.classList.toggle('active', m === 'single');
  applyView(m);
}
elCompare.addEventListener('click', () => setMode('compare'));
elSingle.addEventListener('click', () => setMode('single'));

/* ── guided steps ────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · The frozen instant',
