let stepIdx = 0;
function resetFrozen() { tubes.forEach((t, i) => { t.sphere.position.y = CYL[i].y0; }); }
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  elStepTitle.textContent = s.title;
  elStepText.textContent = s.text;
  s.apply();
}
elPrev.addEventListener('click', () => goToStep(stepIdx - 1));
elNext.addEventListener('click', () => goToStep(stepIdx + 1));

/* ── per-frame update ────────────────────────────────────────────────────── */
function applyFade(t, f) {
  t.fade = f;
  t.group.visible = f > 0.012;
  for (const { m, base } of t.mats) m.opacity = base * f;
}
function placeGlint(t) {
  const s = t.sphere;
  t.glint.position.set(
    s.position.x - 0.10,
    s.position.y + 0.10,
    s.position.z + R_SPH * 0.92
  );
  t.glint.quaternion.copy(camera.quaternion);
}

let _prevT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _prevT) / 1000);
  _prevT = now;

  // fades between the two views
  const tgtC = state.mode === 'compare' ? 1 : 0;
  const tgtS = state.mode === 'single' ? 1 : 0;
  state.fadeCompare += (tgtC - state.fadeCompare) * Math.min(1, dt * 6);
  state.fadeSingle += (tgtS - state.fadeSingle) * Math.min(1, dt * 6);
  tubes.forEach(t => applyFade(t, state.fadeCompare));
  applyFade(single, state.fadeSingle);
  gradeLbls.forEach(l => setLblOpacity(l, state.fadeCompare));
  setLblOpacity(singleGradeLbl, state.fadeSingle);

  // grade sweep tween
  if (state.sweep) {
    state.sweep.t += dt;
    const u = Math.min(1, state.sweep.t / state.sweep.dur);
    setGrade(state.sweep.from + (state.sweep.to - state.sweep.from) * u);
    if (u >= 1) state.sweep = null;
  }

  // four-sphere race
  if (state.race) {
    state.raceT += dt;
    tubes.forEach((t, i) => {
      const fallen = Math.min(FALL, CYL[i].vrel * RACE_SPEED * state.raceT);
      t.sphere.position.y = Y_START - fallen;
    });
    if (state.raceT > FALL / (CYL[3].vrel * RACE_SPEED) + 1.2) state.raceT = 0;
  } else if (state.fadeCompare > 0.01 && Math.abs(tubes[0].sphere.position.y - CYL[0].y0) > 1e-4) {
    tubes.forEach((t, i) => {
      t.sphere.position.y += (CYL[i].y0 - t.sphere.position.y) * Math.min(1, dt * 4);
    });
  }

  // single-cylinder continuous descent
  if (state.fadeSingle > 0.01) {
    const v = (1 / etaFor(state.grade)) * RACE_SPEED;
    state.singleT += dt * v;
    let fallen = state.singleT % (FALL + 0.6);
    if (fallen > FALL) fallen = FALL;
    single.sphere.position.y = Y_START - fallen;
  }

  // glints + terminal-velocity callouts
  const labOn = state.labels ? 1 : 0;
  tubes.forEach((t, i) => {
    placeGlint(t);
    const o = labOn * state.fadeCompare;
    setLblOpacity(velLbls[i], o);
    const y = t.sphere.position.y;
    velLbls[i].pos.set(CYL[i].x + 1.18, y, 0.32);
    const pa = t.leadGeom.attributes.position;
    pa.setXYZ(0, 0.42, y, 0.30); pa.setXYZ(1, 1.02, y, 0.30); pa.needsUpdate = true;
    t.leader.visible = o > 0.05;
  });
  {
    placeGlint(single);
    const o = labOn * state.fadeSingle;
    setLblOpacity(singleVelLbl, o);
    const y = single.sphere.position.y;
    singleVelLbl.pos.set(1.22, y, 0.32);
    const pa = single.leadGeom.attributes.position;
    pa.setXYZ(0, 0.42, y, 0.30); pa.setXYZ(1, 1.06, y, 0.30); pa.needsUpdate = true;
    single.leader.visible = o > 0.05;
  }
}
tick();

